{
  "items": [
    {
      "name": "MvPolynomial.rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {τ : Type u_2} → {R : Type u_4} → [inst : CommSemiring R] → (σ → τ) → MvPolynomial σ R →ₐ[R] MvPolynomial τ R"
    },
    {
      "name": "MvPolynomial.renameEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {τ : Type u_2} → (R : Type u_4) → [inst : CommSemiring R] → σ ≃ τ → MvPolynomial σ R ≃ₐ[R] MvPolynomial τ R"
    },
    {
      "name": "MvPolynomial.coeff_rename_mapDomain",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ),\n  Function.Injective f →\n    ∀ (φ : MvPolynomial σ R) (d : σ →₀ ℕ),\n      MvPolynomial.coeff (Finsupp.mapDomain f d) ((MvPolynomial.rename f) φ) = MvPolynomial.coeff d φ"
    },
    {
      "name": "MvPolynomial.coeff_rename_embDomain",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ ↪ τ) (φ : MvPolynomial σ R) (d : σ →₀ ℕ),\n  MvPolynomial.coeff (Finsupp.embDomain f d) ((MvPolynomial.rename ⇑f) φ) = MvPolynomial.coeff d φ"
    },
    {
      "name": "MvPolynomial.rename_monomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ) (d : σ →₀ ℕ) (r : R),\n  (MvPolynomial.rename f) ((MvPolynomial.monomial d) r) = (MvPolynomial.monomial (Finsupp.mapDomain f d)) r"
    },
    {
      "name": "MvPolynomial.coeff_rename_ne_zero",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ) (φ : MvPolynomial σ R) (d : τ →₀ ℕ),\n  MvPolynomial.coeff d ((MvPolynomial.rename f) φ) ≠ 0 → ∃ u, Finsupp.mapDomain f u = d ∧ MvPolynomial.coeff u φ ≠ 0"
    },
    {
      "name": "MvPolynomial.coeff_rename_eq_zero",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ) (φ : MvPolynomial σ R) (d : τ →₀ ℕ),\n  (∀ (u : σ →₀ ℕ), Finsupp.mapDomain f u = d → MvPolynomial.coeff u φ = 0) →\n    MvPolynomial.coeff d ((MvPolynomial.rename f) φ) = 0"
    },
    {
      "name": "MvPolynomial.degreeOf_coeff_finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {n : ℕ} (p : MvPolynomial (Fin (n + 1)) R) (j : Fin n) (i : ℕ),\n  MvPolynomial.degreeOf j (((MvPolynomial.finSuccEquiv R n) p).coeff i) ≤ MvPolynomial.degreeOf j.succ p"
    }
  ]
}
